  'git.foreign': { en: "The repository lives on a server that cannot be connected here — pull and push are unavailable.", ru: "Репозиторий лежит на сервере, который здесь подключить нельзя, — получение и отправка недоступны.", uk: "Репозиторій лежить на сервері, який тут підключити не можна, — отримання й надсилання недоступні." },
  'git.accounts': { en: "Accounts:", ru: "Аккаунты:", uk: "Акаунти:" },
  'git.accLine': { en: "✅ {host}: {login}", ru: "✅ {host}: {login}", uk: "✅ {host}: {login}" },
  'git.noAccounts': { en: "No accounts connected.", ru: "Аккаунты не подключены.", uk: "Акаунти не підключено." },
  'git.connectFirst': { en: "Connect an account first: /git", ru: "Сначала подключите аккаунт: /git", uk: "Спочатку підключіть акаунт: /git" },
  'git.pull': { en: "⬇️ Pull", ru: "⬇️ Получить", uk: "⬇️ Отримати" },
  'git.push': { en: "⬆️ Push", ru: "⬆️ Отправить", uk: "⬆️ Надіслати" },
  'git.save': { en: "💾 Save and push", ru: "💾 Сохранить и отправить", uk: "💾 Зберегти й надіслати" },
  'git.clone': { en: "⬇️ Clone a repository", ru: "⬇️ Клонировать репозиторий", uk: "⬇️ Клонувати репозиторій" },
  'git.cloneShort': { en: "⬇️ From Git", ru: "⬇️ Из Git", uk: "⬇️ З Git" },
