  'git.accBtn': { en: "✅ {host}: {login}", ru: "✅ {host}: {login}", uk: "✅ {host}: {login}" },
  'git.tokenAsk': { en: "🔑 Connecting {host}\n\n1. Open {url}\n2. Create an access token with these permissions: {scopes}\n3. Send the token here in one message.\n\nThe token is not passed to the agent, and the message with it is deleted from the chat.", ru: "🔑 Подключение {host}\n\n1. Откройте {url}\n2. Создайте токен доступа с правами: {scopes}\n3. Отправьте токен сюда одним сообщением.\n\nАгенту токен не передаётся, а сообщение с ним удаляется из чата.", uk: "🔑 Підключення {host}\n\n1. Відкрийте {url}\n2. Створіть токен доступу з правами: {scopes}\n3. Надішліть токен сюди одним повідомленням.\n\nАгенту токен не передається, а повідомлення з ним видаляється з чату." },
  'git.tokenExpired': { en: "⚠️ The wait for the token has ended. Your message was deleted: nothing was saved and nothing was sent to the agent. Start again: /git", ru: "⚠️ Ожидание токена закончилось. Ваше сообщение удалено: ничего не сохранено и агенту не отправлено. Начните заново: /git", uk: "⚠️ Очікування токена завершилося. Ваше повідомлення видалено: нічого не збережено й агенту не надіслано. Почніть знову: /git" },
  'git.tokenBad': { en: "⚠️ The service did not accept the token. Check that it is copied completely and has not expired, and send it again. Your message was deleted.", ru: "⚠️ Сервис не принял токен. Проверьте, что он скопирован целиком и не истёк, и отправьте ещё раз. Ваше сообщение удалено.", uk: "⚠️ Сервіс не прийняв токен. Перевірте, що його скопійовано повністю і він не прострочений, і надішліть ще раз. Ваше повідомлення видалено." },
  'git.tokenFail': { en: "⚠️ Could not check the token: {msg}. Your message was deleted; send the token again.", ru: "⚠️ Не удалось проверить токен: {msg}. Ваше сообщение удалено; отправьте токен ещё раз.", uk: "⚠️ Не вдалося перевірити токен: {msg}. Ваше повідомлення видалено; надішліть токен ще раз." },
  'git.connected': { en: "✅ {host} connected: {login} ({name}). The message with the token was deleted from the chat.", ru: "✅ {host} подключён: {login} ({name}). Сообщение с токеном удалено из чата.", uk: "✅ {host} підключено: {login} ({name}). Повідомлення з токеном видалено з чату." },
  'git.expires': { en: "The token is valid until {date}.", ru: "Токен действует до {date}.", uk: "Токен дійсний до {date}." },
  'git.scopesWarn': { en: "⚠️ The token lacks permissions: {scopes} — cloning or pushing may not work.", ru: "⚠️ Токену не хватает прав: {scopes} — клонирование или отправка могут не работать.", uk: "⚠️ Токену бракує прав: {scopes} — клонування або надсилання можуть не працювати." },
  'git.accCard': { en: "{host}\nAccount: {login} ({name})\nCommit email: {email}\nToken valid until: {date}", ru: "{host}\nАккаунт: {login} ({name})\nПочта для коммитов: {email}\nТокен действует до: {date}", uk: "{host}\nАкаунт: {login} ({name})\nПошта для комітів: {email}\nТокен дійсний до: {date}" },
  'git.disconnect': { en: "Disconnect", ru: "Отключить", uk: "Відключити" },
  'git.disconnectAsk': { en: "Disconnect {host} ({login})? The token will be removed from the bot.", ru: "Отключить {host} ({login})? Токен будет удалён из бота.", uk: "Відключити {host} ({login})? Токен буде видалено з бота." },
  'git.disconnected': { en: "{host} disconnected.", ru: "{host} отключён.", uk: "{host} відключено." },
  'git.pickHost': { en: "Where to clone from?", ru: "Откуда клонировать?", uk: "Звідки клонувати?" },
  'git.repos': { en: "⬇️ {host} repositories{q}. Choose one to clone into {dir}:", ru: "⬇️ Репозитории {host}{q}. Выберите, какой клонировать в {dir}:", uk: "⬇️ Репозиторії {host}{q}. Оберіть, який клонувати в {dir}:" },
  'git.reposNone': { en: "(no repositories found)", ru: "(репозитории не найдены)", uk: "(репозиторіїв не знайдено)" },
