  'git.searchAsk': { en: "Send a part of the repository name.", ru: "Отправьте часть названия репозитория.", uk: "Надішліть частину назви репозиторію." },
  'git.cloning': { en: "⏳ Cloning {name}…", ru: "⏳ Клонирую {name}…", uk: "⏳ Клоную {name}…" },
  'git.cloned': { en: "✅ The repository {name} was cloned into {p}.", ru: "✅ Репозиторий {name} клонирован в {p}.", uk: "✅ Репозиторій {name} клоновано в {p}." },
  'git.cloneExists': { en: "⚠️ The folder {name} already exists in {dir}. Choose it in /project or rename it.", ru: "⚠️ Папка {name} уже есть в {dir}. Выберите её в /project или переименуйте.", uk: "⚠️ Папка {name} уже є в {dir}. Оберіть її в /project або перейменуйте." },
  'git.cloneBadName': { en: "⚠️ This repository cannot be cloned here: its name is not suitable for a folder.", ru: "⚠️ Этот репозиторий сюда клонировать нельзя: его название не подходит для папки.", uk: "⚠️ Цей репозиторій сюди клонувати не можна: його назва не підходить для папки." },
  'git.opFail': { en: "⚠️ Git: {msg}", ru: "⚠️ Git: {msg}", uk: "⚠️ Git: {msg}" },
  'git.busy': { en: "Wait for the current Git operation to finish.", ru: "Дождитесь завершения текущей операции Git.", uk: "Дочекайтеся завершення поточної операції Git." },
  'git.agentBusy': { en: "First wait for the agent to answer or stop it: /stop", ru: "Сначала дождитесь ответа агента или остановите его: /stop", uk: "Спочатку дочекайтеся відповіді агента або зупиніть його: /stop" },
  'git.pulling': { en: "⏳ Pulling changes…", ru: "⏳ Получаю изменения…", uk: "⏳ Отримую зміни…" },
  'git.pull.updated': { en: "✅ Changes received.", ru: "✅ Изменения получены.", uk: "✅ Зміни отримано." },
  'git.pull.uptodate': { en: "✅ There are no new changes on the server.", ru: "✅ Новых изменений на сервере нет.", uk: "✅ Нових змін на сервері немає." },
  'git.pull.diverged': { en: "⚠️ You and the server have different changes. Ask the agent to merge them (for example: “merge the changes from the server”) and then push.", ru: "⚠️ У вас и на сервере разные изменения. Попросите агента объединить их (например: «объедини изменения с сервера») и затем отправьте.", uk: "⚠️ У вас і на сервері різні зміни. Попросіть агента об’єднати їх (наприклад: «об’єднай зміни з сервера») і потім надішліть." },
  'git.pull.noupstream': { en: "ℹ️ This branch is not on the server yet — press “Push”.", ru: "ℹ️ Этой ветки ещё нет на сервере — нажмите «Отправить».", uk: "ℹ️ Цієї гілки ще немає на сервері — натисніть «Надіслати»." },
  'git.pushing': { en: "⏳ Pushing…", ru: "⏳ Отправляю…", uk: "⏳ Надсилаю…" },
