  'git.nothingToPush': { en: "ℹ️ Nothing to push: everything is already on the server.", ru: "ℹ️ Отправлять нечего: всё уже на сервере.", uk: "ℹ️ Надсилати нічого: усе вже на сервері." },
  'git.pushRejected': { en: "⚠️ The server rejected the push: it has newer changes. Press “Pull” first.", ru: "⚠️ Сервер не принял отправку: на нём есть более новые изменения. Сначала нажмите «Получить».", uk: "⚠️ Сервер не прийняв надсилання: на ньому є новіші зміни. Спочатку натисніть «Отримати»." },
  'git.secretsWarn': { en: "⚠️ The commits that are not pushed yet contain files with secrets:\n{files}\nAfter pushing they will be on the server.", ru: "⚠️ В коммитах, которые ещё не отправлены, есть файлы с секретами:\n{files}\nПосле отправки они окажутся на сервере.", uk: "⚠️ У комітах, які ще не надіслано, є файли із секретами:\n{files}\nПісля надсилання вони опиняться на сервері." },
  'git.pushAnyway': { en: "Push anyway", ru: "Отправить всё равно", uk: "Надіслати все одно" },
  'git.messageAsk': { en: "💾 Send a short description of the changes in one message — or press “No description”.", ru: "💾 Отправьте краткое описание изменений одним сообщением — или нажмите «Без описания».", uk: "💾 Надішліть короткий опис змін одним повідомленням — або натисніть «Без опису»." },
  'git.noMessage': { en: "No description", ru: "Без описания", uk: "Без опису" },
